import{_ as i,c as l,o as e,a3 as r}from"./chunks/framework.CoV49S2T.js";const p=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy.md","filePath":"zh-CN/guide/privacy.md","lastUpdated":1787284674000}'),t={name:"zh-CN/guide/privacy.md"};function o(s,a,n,c,h,d){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>ClipboxAI 是一款面向 macOS 的智能剪贴板管理器。你的隐私是我们的首要考量。</p><h2 id="本地优先设计-local-first-design" tabindex="-1">本地优先设计（Local-First Design） <a class="header-anchor" href="#本地优先设计-local-first-design" aria-label="Permalink to &quot;本地优先设计（Local-First Design）&quot;">​</a></h2><ul><li>你的剪贴板历史完全保存在你的 Mac 上。</li><li>内置本地操作（提取链接、字数统计、压缩空行，以及设备端 ML 建议）完全离线运行。</li><li>使用核心应用无需账号或注册。</li><li>本地剪贴板管理与设备端功能无需网络连接。</li></ul><h2 id="云端-ai-可选-cloud-ai" tabindex="-1">云端 AI（可选，Cloud AI） <a class="header-anchor" href="#云端-ai-可选-cloud-ai" aria-label="Permalink to &quot;云端 AI（可选，Cloud AI）&quot;">​</a></h2><p>ClipboxAI 可选择使用云端 AI 提供商（如 DeepSeek、MiniMax、GLM、Kimi、Mistral，或本地 Ollama 服务器）来支撑总结、翻译、自定义提示等高级操作。</p><ul><li>启用后，所选文本或剪贴内容会使用<strong>你自己的 API key</strong>，<strong>直接发送到你配置的提供商</strong>。</li><li>你的 API key 仅保存在你 Mac 的 Keychain 中，绝不会上传给我们。</li><li>你可以随时关闭云端 AI，继续使用本地功能。</li><li>剪贴板历史<strong>不会</strong>自动发送到云端；云端请求仅在你运行某项云端操作时才会触发。</li></ul><h2 id="我们不作收集的内容" tabindex="-1">我们不作收集的内容 <a class="header-anchor" href="#我们不作收集的内容" aria-label="Permalink to &quot;我们不作收集的内容&quot;">​</a></h2><ul><li>我们不收集你的剪贴板内容、文档或文件。</li><li>我们不追踪你的活动、浏览行为或使用模式。</li><li>我们不运营任何接收你剪贴板数据的服务器。</li><li>我们不包含任何第三方分析、广告或追踪 SDK。</li><li>我们没有任何遥测系统。</li></ul><h2 id="本地存储哪些数据" tabindex="-1">本地存储哪些数据 <a class="header-anchor" href="#本地存储哪些数据" aria-label="Permalink to &quot;本地存储哪些数据&quot;">​</a></h2><p>以下数据仅保存在你的设备上：</p><ul><li><strong>剪贴板历史</strong>：便于快速访问的最近条目（保存在你的 Mac 上）。</li><li><strong>应用设置</strong>：主题、语言偏好、已启用操作、提供商配置。</li><li><strong>API key</strong>：安全地保存在本地 Keychain 中（仅在你配置了云端提供商时）。</li><li><strong>自定义操作</strong>：你创建的提示词与配置。</li><li><strong>日志</strong>：用于故障排除的调试日志（可随时删除）。</li></ul><h2 id="应用使用的权限" tabindex="-1">应用使用的权限 <a class="header-anchor" href="#应用使用的权限" aria-label="Permalink to &quot;应用使用的权限&quot;">​</a></h2><ul><li><strong>辅助功能 / 完全磁盘访问（Accessibility / Full Disk Access）</strong>：读取系统剪贴板并提供全局快捷键所需。</li><li><strong>通知（Notifications）</strong>：可选，用于长时间云请求的完成提醒。</li></ul><p>你可以随时在 <strong>系统设置 → 隐私与安全性（System Settings → Privacy &amp; Security）</strong> 中管理这些权限。</p><h2 id="应用内购买-许可" tabindex="-1">应用内购买 / 许可 <a class="header-anchor" href="#应用内购买-许可" aria-label="Permalink to &quot;应用内购买 / 许可&quot;">​</a></h2><p>许可购买（如有）由 Apple 通过 Mac App Store 处理。ClipboxAI 不接收或存储你的支付信息。许可凭证保存在本地以验证所有权。</p><h2 id="第三方服务" tabindex="-1">第三方服务 <a class="header-anchor" href="#第三方服务" aria-label="Permalink to &quot;第三方服务&quot;">​</a></h2><p>ClipboxAI 本身不包含任何第三方分析、广告或追踪服务。当你启用某个云端 AI 提供商时，你的请求由该提供商按其自身的隐私政策处理。</p><h2 id="隐私请求" tabindex="-1">隐私请求 <a class="header-anchor" href="#隐私请求" aria-label="Permalink to &quot;隐私请求&quot;">​</a></h2><p>由于 ClipboxAI 将所有数据本地保存在你的设备上，我们的服务器上不持有任何个人数据。如果你对隐私有疑问，请联系我们。</p><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>如有隐私相关问题，请在 <a href="https://github.com/clipboxAI/clipboard-site/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 上提交 issue，或发送邮件至 <a href="mailto:clipboxai@w3cub.com" target="_blank" rel="noreferrer">clipboxai@w3cub.com</a>。</p>',23)])])}const b=i(t,[["render",o]]);export{p as __pageData,b as default};
